def is_langford(seq, n):
    positions = [[] for _ in range(n+1)]
    for i, num in enumerate(seq):
        positions[num].append(i)
    for v in range(1, n+1):
        if len(positions[v]) != 2:
            return False
        diff = positions[v][1] - positions[v][0]
        if diff != v + 1:
            return False
    return True

from itertools import permutations

def find_langford(n=6):
    nums = list(range(1,n+1))*2
    for p in set(permutations(nums)):
        if is_langford(p, n):
            return p
    return None

result = find_langford()
print(result)

def langford(n=6):
    seq = [0] * (2 * n)
    used = [False] * (n + 1)

    def backtrack(pos):
        if pos == len(seq):
            return True
        if seq[pos] != 0:
            return backtrack(pos + 1)
        for v in range(n, 0, -1):  # start with larger numbers
            if not used[v]:
                d = v + 1
                if pos + d < len(seq) and seq[pos + d] == 0:
                    seq[pos] = v
                    seq[pos + d] = v
                    used[v] = True
                    if backtrack(pos + 1):
                        return True
                    seq[pos] = 0
                    seq[pos + d] = 0
                    used[v] = False
        return False

    if backtrack(0):
        return seq
    return "UNSATISFIABLE"

result = langford()
print(result)
